#!/usr/bin/env node
import fs from "node:fs";

const read=path=>fs.readFileSync(path,"utf8");
const write=(path,content)=>fs.writeFileSync(path,content,"utf8");

function replaceOnce(path,before,after,label){
  const source=read(path);
  const first=source.indexOf(before);
  if(first<0){ throw new Error(`Missing replacement target (${label}) in ${path}`); }
  if(source.indexOf(before,first+before.length)>=0){ throw new Error(`Ambiguous replacement target (${label}) in ${path}`); }
  write(path,source.slice(0,first)+after+source.slice(first+before.length));
}
function replaceRegex(path,regex,after,label){
  const source=read(path);
  const matches=[...source.matchAll(new RegExp(regex.source,regex.flags.includes("g")?regex.flags:regex.flags+"g"))];
  if(matches.length!==1){ throw new Error(`Expected 1 regex target (${label}) in ${path}, got ${matches.length}`); }
  write(path,source.replace(regex,after));
}
function prepend(path,text){ write(path,text+read(path)); }

